"""Informe de auditoría y priorización; lee salidas congeladas, sin modificar panel."""
from pathlib import Path
import sys,json,hashlib
import pandas as pd
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from src.clasificacion_sectorial import read_panel
OUT=ROOT/'reports/sprint_07/fase_3';BASE=ROOT/'data/raw/sectorial_fase3'
def main():
    p=read_panel(ROOT)
    old=pd.read_csv(ROOT/'reports/sprint_07/enriquecimiento/catalogo_empresa_anio.csv',dtype={'RPJ':str})
    c=pd.read_csv(OUT/'catalogo_empresa_anio.csv',dtype={'RPJ':str})
    ev=pd.read_csv(BASE/'evidencias_actividad.csv',dtype=str,keep_default_na=False)
    m=pd.read_csv(OUT/'catalogo_maestro_empresas.csv',dtype={'RPJ':str})
    joined=p.merge(c[['RPJ','Ejercicio','industria_damodaran']],on=['RPJ','Ejercicio'],validate='one_to_one')
    prev=p.merge(old[['RPJ','Ejercicio','industria_damodaran']],on=['RPJ','Ejercicio'],validate='one_to_one')
    old_master=pd.read_csv(ROOT/'reports/sprint_07/enriquecimiento/catalogo_maestro_empresas.csv',dtype={'RPJ':str})
    fields=['RPJ','actividad_principal_documentada','fuente_actividad','anio_referencia_actividad']
    selected=old_master[fields].merge(m[fields+['evidencia_resumen_seleccionada','criterio_seleccion']],on='RPJ',suffixes=('_fase2','_fase3'),validate='one_to_one')
    selected['cambio_fuente_resumen']=selected.fuente_actividad_fase2.fillna('').ne(selected.fuente_actividad_fase3.fillna(''))
    selected.to_csv(OUT/'comparacion_resumen_documental.csv',index=False)
    counts=[]
    for phase,g in [('Fase 2',prev),('Fase 3',joined)]:
        for partition in ['entrenamiento','prueba']:
            h=g.loc[g.utilizable_supervisado & g.particion.eq(partition) & g.industria_damodaran.notna()]
            counts.append({'fase':phase,'particion':partition,'observaciones_clasificadas_elegibles':len(h),'empresas_distintas_RPJ':h.RPJ.nunique()})
    pd.DataFrame(counts).to_csv(OUT/'comparacion_elegibilidad.csv',index=False)
    delta=c.merge(old[['RPJ','Ejercicio','industria_damodaran']],on=['RPJ','Ejercicio'],suffixes=('','_fase2'),validate='one_to_one')
    added=delta.loc[delta.industria_damodaran_fase2.isna() & delta.industria_damodaran.notna()]
    added.to_csv(OUT/'observaciones_nuevas.csv',index=False)
    added.groupby(['RPJ','NombreEmpresa','industria_damodaran'],dropna=False).agg(observaciones_nuevas=('Ejercicio','size'),anios_nuevos=('Ejercicio',lambda s:'|'.join(map(str,sorted(s))))).reset_index().to_csv(OUT/'empresas_ampliadas.csv',index=False)
    rows=[]
    for spec in json.loads((BASE/'descargas.json').read_text()):
        e=ev.loc[ev.fuente_id.eq(spec['id'])];err=BASE/(spec['id']+'.error.json')
        error=json.loads(err.read_text())['error'] if err.exists() else ''
        rows.append({'fuente_id':spec['id'],'url':spec['url'],'RPJ':'|'.join(sorted(set(e.RPJ))),
            'estado':'Evidencia específica verificada' if len(e) else 'Documento conservado sin asignación' if (BASE/(spec['id']+'.pdf')).exists() else 'No recuperado; no asigna',
            'anios_explicitamente_respaldados':' / '.join(e.anios_respaldados),'paginas_pdf':'|'.join(e.pagina_pdf),
            'industria':'|'.join(sorted(set(e.industria_propuesta)-{''})),'error_recuperacion':error,
            'nota':'Hermes: informe de clasificadora, no evidencia empresarial primaria; excluido' if spec['id']=='hermes20' else ''})
    rows.append({'fuente_id':'ingenio_portal','url':'https://agroingenio.pe/memorias.html','RPJ':'017070','estado':'Portal no recuperado; no asigna','error_recuperacion':'Fallo DNS en descarga y timeout en consulta web; pendiente recuperar memorias históricas'})
    pd.DataFrame(rows).to_csv(OUT/'bitacora_investigacion_fase3.csv',index=False)
    cases=[('B20003','Minería','Metals & Mining | Precious Metals','Polimetálica, con oro y plata relevantes. Aprobar criterio de frontera industrial y evaluar segmentos; PDF 100–101.'),
        ('A20032','Minería','Metals & Mining','Asignación 2019–2020 por predominancia del estaño (>70% de ventas en ambos años, PDF 75); revisar criterio académico de actividad principal.'),
        ('B30060','Manufactura','Apparel','CIIU 1311 acreditado, hilados/tejidos/confecciones integrados. Industria pendiente; no equiparar automáticamente textil con confecciones.'),
        ('CI0009','Transporte por ductos','Oil/Gas Distribution','Actividad acreditada 2018–2019. Midstream no existe en las 94 etiquetas congeladas; aprobar correspondencia con alcance oficial antes de asignar.'),
        ('J40655','Transporte ferroviario','Transportation (Railroads)','Documento SMV localizado pero HTTP 403; no asignado a partir de buscadores, tesis o razón social.'),
        ('017070','Agroindustria','','Alta prioridad por muestra elegible; portal primario inaccesible. Obtener memorias, no copiar actividad de otra azucarera.'),
        ('B08363','Agroindustria','Food Processing','Código CIIU impreso extraído como 10721 con llamada de nota; no truncar ni generar CIIU histórico sin cotejo de página.'),
        ('000355','Construcción','Engineering/Construction','La memoria 2020 distingue operador de construcción y holding; mantener otros años pendientes hasta acreditar continuidad.'),
        ('B30241','Publicaciones','Publishing & Newspapers','Clasificación 2025 de entidad separada; no atribuir televisión de subsidiarias ni retroceder a 2024 sin continuidad probada.'),
        ('B40002','Electricidad','Power','Entidad canónica única con dos localizadores históricos. Las filas por localizador no son empresas ni nuevas observaciones.'),
        ('B30121','Holding','','Reorganización de UNACEM: no trasladar producción de subsidiarias a matriz ni extender actividad a otros períodos.'),
        ('B80004','Financiero','','Mantener pendiente frontera bancaria de Damodaran; validar FCL económico como objetivo adecuado para bancos.'),
        ('B80020','Financiero','','Mantener pendiente frontera bancaria de Damodaran; validar FCL económico como objetivo adecuado para bancos.')]
    review=pd.DataFrame(cases,columns=['RPJ','sector_revision','industrias_candidatas_no_equivalen_a_asignacion','revision_requerida']).merge(m[['RPJ','NombreEmpresa','estado_clasificacion','observaciones_pendientes']],on='RPJ',validate='one_to_one')
    review.to_csv(OUT/'revision_academica.csv',index=False)
    audit=json.loads((OUT/'auditoria_enriquecimiento.json').read_text());a=audit['cobertura_fase2'];z=audit['cobertura_nueva']
    sufficient=pd.read_csv(OUT/'suficiencia_muestral.csv');power=sufficient.loc[sufficient.industria_damodaran.eq('Power') & sufficient.Moneda.eq('Soles')].iloc[0]
    sources=sum((BASE/(s['id']+'.pdf')).exists() for s in json.loads((BASE/'descargas.json').read_text()))
    text=f'''# Sprint 07 — Fase 3: corrección y ampliación sectorial\n\nRama local `sprint-07-clasificacion-sectorial`. Catálogo: 336 empresas, 4221 observaciones empresa-año. No se entrenaron modelos, modificaron FCL, variables financieras, división temporal ni datos originales; no se realizó commit, push, PR ni cambios en main.\n\n## Resultado comparativo\n\n| Indicador | Fase 2 congelada | Fase 3 |\n|---|---:|---:|\n| Empresas con alguna observación clasificada | {a['empresas_con_alguna_clasificacion']} | {z['empresas_con_alguna_clasificacion']} |\n| Empresas completamente clasificadas | {a['empresas_clasificadas']} | {z['empresas_clasificadas']} |\n| Empresas parcialmente clasificadas | {a['empresas_parcialmente_clasificadas']} | {z['empresas_parcialmente_clasificadas']} |\n| Empresas sin clasificación | {a['empresas_pendientes']} | {z['empresas_pendientes']} |\n| Observaciones clasificadas | {a['observaciones_clasificadas']} | {z['observaciones_clasificadas']} |\n| Observaciones pendientes | {a['observaciones_pendientes']} | {z['observaciones_pendientes']} |\n| Industrias representadas | {a['industrias']} | {z['industrias']} |\n\nSe agregaron {len(added)} observaciones en {added.RPJ.nunique()} empresas, conservando las 442 asignaciones de Fase 2. La cobertura continúa limitada: {z['observaciones_clasificadas']/4221:.2%} de las observaciones y {z['empresas_con_alguna_clasificacion']/336:.2%} de las empresas tienen alguna clasificación. Las empresas parcialmente clasificadas conservan sus años pendientes: no se certifica toda su historia.\n\n`comparacion_elegibilidad.csv` separa entrenamiento/prueba de la cobertura total; `observaciones_nuevas.csv` identifica cada incorporación. No se utilizaron resultados de modelos, FCL ni métricas predictivas para priorizar.\n\n## Cinco correcciones auditadas\n\n1. **D04: inversión y actividad separadas.** Cero, vacío y valores no positivos no acreditan ausencia de operación. Se conserva la regla previamente aceptada de inversión positiva como indicio sectorial condicionado al sector SMV; D03 aporta evidencia empresarial independiente. Hidrandina 2015, Piura 2021–2022 y REP 2022 ahora cuentan con pasajes de actividad del ejercicio. `revision_actividad_inversion.csv` conserva todos los localizadores, estado de inversión, estado de actividad y respaldo final; `evidencias_estadisticas_empresa_anio.csv` conserva solo localizadores asignables por la regla original. No rellenar huecos automáticamente.\n2. **Maestro documental.** Selección: vigencia en el último ejercicio del panel, certeza de actividad, jerarquía documental y año. Si no hay evidencia vigente, resume la referencia documental más reciente y la identifica explícitamente; no extiende esa actividad a años sin respaldo. Jerarquía: EEFF individual auditado 5, memoria 4, documento empresarial primario aún no normalizado 4, nota individual no auditada 3, descripción de entidad consolidada 2, estadística sectorial 1. Se rechazan industrias contradictorias de igual calidad/vigencia. ID y orden de filas no determinan calidad. El resumen incluye el ID seleccionado y el criterio; los cambios de redacción no crean falsos cambios económicos ni huecos.\n3. **Hidrandina.** `correspondencia_minem_canonica.csv` contiene 24 RPJ únicos frente a 25 localizadores originales. Hidrandina conserva sus dos series y sus años de inversión positiva, incluida la historia anterior a 2005, dentro de un solo registro empresarial. Las cinco celdas de los cuatro huecos eléctricos incluyen dos localizadores de Hidrandina, no cinco observaciones. El archivo original se preserva.\n4. **Notebook.** Ruta canónica `notebooks/sprint_07/10_clasificacion_sectorial.ipynb`; la ruta anterior `notebooks/08_clasificacion_sectorial.ipynb` es enlace simbólico de compatibilidad. El único notebook físico 08 de raíz sigue siendo `08_mejoras_baseline.ipynb`, sin modificar. `notebooks/README.md` documenta inventario y limitación del glob histórico del notebook 09. El notebook canónico fue ejecutado sin entrenamiento; ambas rutas leen el mismo archivo.\n5. **Suficiencia.** Se mantienen umbrales originales por industria y moneda: al menos 5 RPJ, 30 observaciones elegibles de entrenamiento y 10 de prueba. Se agregan conteos de RPJ y años objetivo por partición, y una condición conservadora de 5 RPJ distintos en cada partición para recomendar experimentos. Repetir años de una empresa no crea empresas independientes. Los RPJ son entidades legales distintas: no prueban independencia económica entre miembros de un grupo.\n\n## Ampliación y priorización\n\n`priorizacion_inicial.csv` ordena todas las empresas con años pendientes de la Fase 2 por observaciones elegibles pendientes, presencia en ambas particiones y conteos train/test; `priorizacion_pendientes.csv` actualiza el orden tras la ampliación. Incluyen financieros; no se omiten bancos por el foco no financiero.\n\nLa investigación añadió {len(ev)} evidencias específicas de {ev.RPJ.nunique()} empresas y conservó {sources} PDF nuevos, además de intentos fallidos y portales. Se revisaron minería (Minsur y Buenaventura), construcción (Cosapi), manufactura (Yura, Siderperú, Creditex), retail (Supermercados Peruanos), agroindustria (Laredo, Cartavio, Casa Grande y Agrícola San Juan), transporte (TGP; Inca Rail pendiente de descarga), electricidad y publicaciones (El Comercio). La bitácora distingue documentos utilizables, fuentes sin asignación y accesos fallidos; Hermes se excluye porque el documento recuperado es de una clasificadora, no de la empresa. No se asignó por nombre ni por un resultado del buscador.\n\nLas nuevas industrias representadas son Farming/Agriculture, Publishing & Newspapers y Retail (Grocery and Food). El incremento documental es deliberadamente acotado a los años acreditados; no elimina la insuficiencia de muestra de estos sectores.\n\nLas fuentes primarias se conservan en `data/raw/sectorial_fase3/`: PDF, texto paginado, URL consultada/final, fecha, huellas SHA-256 y manifiesto de descarga. `evidencias_actividad.csv` incluye identidad RPJ/RUC, razón social documental, actividad, alcance temporal, página, extracto literal, certeza y clase documental. La validación comprueba entidad literal, pasaje en página, identidad exacta del panel, años y vocabulario de 94 industrias. Las memorias y EEFF comparativos acreditan solo períodos explícitos; las notas intermedias son fotografías intraanuales, no prueba de actividad durante cada día del año.\n\nCIIU no se genera desde una actividad ni desde la industria. Se registran códigos explícitos de Cosapi (4390), Creditex (1311) y Agrícola San Juan (0121, 0114, 0122, 0111), separados del original. Laredo requiere cotejo de la llamada de nota que el extractor une al código. No se hizo consulta individual SUNAT: RUC válido significa control formal, no alta/estado registral ni actividad histórica acreditada por SUNAT. La taxonomía 2026 es un instrumento retrospectivo; esta entrega no certifica disponibilidad point-in-time.\n\n## Industrias con muestra para experimentos posteriores\n\nSolo **Power / Soles** supera ambos controles orientativos: {power.empresas_panel} empresas del panel, {power.empresas_entrenamiento} RPJ distintos y {power.observaciones_entrenamiento} filas elegibles en entrenamiento, {power.empresas_prueba} RPJ distintos y {power.observaciones_prueba} filas en prueba. No se entrenó ningún modelo.\n\nInvestments & Asset Management / Soles supera el umbral original (63 filas train, 16 test), pero solo tiene 4 empresas en prueba; queda fuera de la recomendación ampliada. Además exige validación académica del FCL como objetivo financiero. Power en dólares y todas las demás combinaciones industria/moneda siguen con muestra insuficiente. No combinar monedas ni extender períodos para superar umbrales.\n\n## Revisión académica y entrega a Antigravity\n\n`revision_academica.csv` contiene identidades y acciones por caso: frontera minería polimetálica/metales preciosos, predominancia del estaño en Minsur, textiles, transporte por ductos sin etiqueta Midstream oficial, atribución matriz/subsidiarias, documentación inaccesible y CIIU. No se consideran asignaciones las categorías candidatas de revisión. Los {z['empresas_pendientes']} RPJ de `empresas_pendientes.csv` y los {z['empresas_parcialmente_clasificadas']} de `empresas_parcialmente_clasificadas.csv` requieren ampliar documentación en sus ejercicios faltantes.\n\nAuditoría independiente: contrastar fuente y página, vigencia y perímetro, comprobar los SHA-256 del JSON, y reproducir sin red. Fase 2 y sus fuentes permanecen congeladas y verificadas por huella antes de cada ejecución. Los controles de unión preservan exactamente todas las columnas financieras, FCL, elegibilidad y particiones.\n\n## Validación y reproducción\n\n- `python scripts/reproduce_enriquecimiento_sectorial.py`: reproduce catálogos Fase 3 sin red ni lector PDF.\n- `python scripts/reporte_sectorial_fase3.py`: genera este informe y los anexos de auditoría.\n- `python -m unittest discover -s tests -v`: **44 pruebas aprobadas**, 35 anteriores y 9 nuevas; registro en `pruebas_automatizadas.txt`.\n- Notebook canónico: 15 celdas de código ejecutadas, sin errores ni entrenamiento.\n\nLas pruebas cubren inversión cero/vacía, prioridad documental independiente del ID/orden, vigencia, deduplicación histórica, alias del notebook, número de empresas frente a filas, priorización elegible, estabilidad semántica y respaldo anual de toda ampliación. Se conservan las verificaciones anteriores de integridad, CIIU, conflictos y reproducibilidad exacta.\n'''
    (OUT/'informe_fase3.md').write_text(text)
if __name__=='__main__':main()
